// FRACTALOpen opens a live [FRACTALStream] on a warm-up history, oldest bar
// first, and returns it with its values at the last history bar (outSwingHigh
// and outSwingLow), the values [Core.FRACTAL] writes there.
//
// inHigh and inLow are the histories, of one length; the parameters are those
// of [Core.FRACTAL].
//
// The error is [InsufficientHistory] for a history of at most
// [Core.FRACTALLookback] bars, and [BadParam] for a parameter out of range or
// histories of different lengths.
func (c *Core) FRACTALOpen(inHigh, inLow []float64, optInLeftBars, optInRightBars int) (*FRACTALStream, int32, int32, error) {
	if !fitsInt32(optInLeftBars) {
		return nil, 0, 0, BadParam
	}
	if !fitsInt32(optInRightBars) {
		return nil, 0, 0, BadParam
	}
	sp, err := c.fractalOpenInternal(inHigh, inLow, 0, int32(optInLeftBars), int32(optInRightBars))
	if err != nil {
		return nil, 0, 0, err
	}
	return sp, sp.cur_outSwingHigh, sp.cur_outSwingLow, nil
}

